import type { CharacterId, Pose } from './art';

/**
 * Full-body poses the web stages use. Each gets a transparent cutout generated by
 * `npm run cutouts` (scripts/gen-cutouts.ts) into src/art/cutouts/.
 * Add a pair here before using it with stagePose().
 */
export const STAGE_POSES = [
  ['judge', 'idle'],
  ['judge', 'idle_b'],
  ['defense', 'idle_a'],
  ['defense', 'laughing'],
  ['prosecutor', 'objection'],
  ['prosecutor', 'talking'],
  ['side-a', 'talking'],
  ['side-b', 'angry'],
  ['juror', 'idle'],
] as const satisfies ReadonlyArray<readonly [CharacterId, Pose]>;

export type StagePose = (typeof STAGE_POSES)[number];
